"""Effect catalogue loaded from ``data/effects.json`` (generated by tools/build_catalog.py).

Raw value encoding [I], fitted to 200 presets read from a real GE150 (plan.md §2.7):
``raw = round((value - min(min, 0)) / step)``. Negative ranges are shifted (EQ 0 dB = 16,
PITCH 0.0 = 120, DETUNE 0.0 = 200) and positive ranges are stored as-is (delay TIME
40..2500 ms is stored in ms). Enums store the option index.
Each parameter also knows its ``word`` (index inside the module block).
"""

from __future__ import annotations

import json
from dataclasses import dataclass
from functools import cache
from importlib import resources
from typing import Any

from ge150.model.preset import MODULES


@dataclass(frozen=True)
class Param:
    name: str
    kind: str  # "number" | "enum" | "raw"
    min: float = 0
    max: float = 0
    step: float = 1
    decimals: int = 0
    unit: str = ""
    options: tuple[str, ...] = ()
    word: int = 2

    @property
    def offset(self) -> float:
        return min(self.min, 0)

    @property
    def raw_max(self) -> int:
        if self.kind == "enum":
            return len(self.options) - 1
        return round((self.max - self.offset) / self.step)

    def to_raw(self, value: float | str) -> int:
        if self.kind == "enum":
            index = self.options.index(value) if isinstance(value, str) else int(value)
            if not 0 <= index < len(self.options):
                raise ValueError(f"{self.name}: option index out of range")
            return index
        number = float(value)
        if not self.min <= number <= self.max:
            raise ValueError(f"{self.name}: {number} outside {self.min}..{self.max}")
        return round((number - self.offset) / self.step)

    def from_raw(self, raw: int) -> float | str:
        if self.kind == "enum":
            return self.options[raw] if 0 <= raw < len(self.options) else f"?{raw}"
        value = self.offset + raw * self.step
        return round(value, self.decimals) if self.decimals else round(value)

    def format(self, raw: int) -> str:
        value = self.from_raw(raw)
        if isinstance(value, str):
            return value
        text = f"{value:.{self.decimals}f}"
        return f"{text} {self.unit}".strip()


@dataclass(frozen=True)
class Model:
    number: int  # as shown by the pedal ("01:CRY WAH" -> 1)
    name: str
    params: tuple[Param, ...]
    user_slot: bool = False
    hidden: bool = False

    @property
    def label(self) -> str:
        return f"{self.number:02d}:{self.name}"


@dataclass(frozen=True)
class ModuleInfo:
    index: int
    name: str
    models: tuple[Model, ...]

    def model_for_type(self, type_word: int) -> Model | None:
        """Model for a TYPE word. TYPE is 0-based (number - 1), verified on 200 presets."""
        if 0 <= type_word < len(self.models):
            return self.models[type_word]
        return None


def _param(data: dict[str, Any]) -> Param:
    if data["kind"] == "enum":
        return Param(data["name"], "enum", options=tuple(data["options"]), word=data["word"])
    if data["kind"] == "number":
        return Param(data["name"], "number", data["min"], data["max"], data["step"],
                     data["decimals"], data.get("unit", ""), word=data["word"])
    return Param(data["name"], "raw", word=data["word"])


@cache
def load_catalog() -> tuple[ModuleInfo, ...]:
    text = resources.files("ge150.data").joinpath("effects.json").read_text()
    raw = json.loads(text)
    modules = []
    for m in raw["modules"]:
        models = tuple(
            Model(x["number"], x["name"], tuple(_param(p) for p in x["params"]),
                  x.get("user_slot", False), x.get("hidden_in_vendor_ui", False))
            for x in m["models"]
        )
        modules.append(ModuleInfo(m["index"], m["name"], models))
    if [m.name for m in modules] != [layout.name for layout in MODULES]:
        raise ValueError("effects.json module order does not match the preset layout")
    return tuple(modules)
